]$mounts$::jsonb) AS t(collection text,code text,name text,sha256 text,depth numeric)
)
UPDATE dndshare.map_model model
SET geometry=model.geometry || jsonb_build_object('mountDepth',mounts.depth)
FROM mounts
WHERE model.collection=mounts.collection AND model.source_code=mounts.code AND model.source_name=mounts.name
AND model.assets->'source'->>'sha256'=mounts.sha256;

ALTER TABLE dndshare.map_model ADD CONSTRAINT map_model_mount_depth_check CHECK (
 jsonb_typeof(geometry->'mountDepth')='number' AND (geometry->>'mountDepth')::numeric>=0
 AND (geometry->>'mountDepth')::numeric<=(geometry->>'surfaceHeight')::numeric
);
